  if (patron.test(input.trim())) {
    throw new Error(`FORMATO NO PERMITIDO: "${input}". El agente debe pasar el texto original del usuario (ej: "viernes a las 4pm", "28 de julio"), no fechas calculadas.`);
  }
}

// 2. Configuración
const MESES = {
  'enero': 0, 'febrero': 1, 'marzo': 2, 'abril': 3, 'mayo': 4, 'junio': 5,
  'julio': 6, 'agosto': 7, 'septiembre': 8, 'octubre': 9, 'noviembre': 10, 'diciembre': 11
};

const DIAS_SEMANA = {
  'domingo': 0, 'lunes': 1, 'martes': 2, 'miercoles': 3,
  'jueves': 4, 'viernes': 5, 'sabado': 6
};

// 3. Funciones auxiliares
function obtenerFechaActualMTY() {
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  return new Date(utc + (-5 * 3600000));
}

function normalizarTexto(texto) {
  return texto.toLowerCase()
              .trim()
              .replace(/á/g, 'a')
              .replace(/é/g, 'e')
              .replace(/í/g, 'i')
              .replace(/ó/g, 'o')
              .replace(/ú/g, 'u')
              .replace(/ñ/g, 'n');
}

function parsearHora(texto, fechaBase = null) {
  // Buscar patrones de hora - mejorados para capturar más formatos
  const patrones = [
    /(\d{1,2}):(\d{2})\s*(am|pm)?/i,           // 14:30, 2:30 PM
    /(\d{1,2})\s*(am|pm)/i,                    // 2 PM, 9 AM, 11 am
    /(\d{1,2})\s*h/i,                          // 14h, 9h
    /las\s+(\d{1,2})\s*(am|pm)?/i,             // las 4, las 11 am
    /a\s+las\s+(\d{1,2})\s*(am|pm)?/i          // a las 11 am
  ];

  for (const patron of patrones) {
    const match = texto.match(patron);
    if (match) {
      let hora = parseInt(match[1], 10);
      let minuto = match[2] && !isNaN(parseInt(match[2])) ? parseInt(match[2], 10) : 0;
      const meridiem = match[2] && isNaN(parseInt(match[2])) ? match[2].toLowerCase() : 
                      match[3] ? match[3].toLowerCase() : null;

      // Validar rangos
      if (hora < 0 || hora > 23 || minuto < 0 || minuto > 59) continue;

      // Ajustar AM/PM
      if (meridiem) {
        if (meridiem === 'pm' && hora < 12) hora += 12;
        if (meridiem === 'am' && hora === 12) hora = 0;
      }

      return { hora, minuto };
    }
  }

  return { hora: 9, minuto: 0 }; // Default
}

function crearFecha(año, mes, dia, hora = 9, minuto = 0) {
  const fecha = new Date(año, mes, dia, hora, minuto, 0, 0);

  // Validar que la fecha sea real
  if (fecha.getFullYear() !== año || fecha.getMonth() !== mes || fecha.getDate() !== dia) {
    return null;
  }

  return fecha;
}

function validarHorarioNegocio(fecha) {
  const dia = fecha.getDay();
  const hora = fecha.getHours();

  return (dia >= 1 && dia <= 5 && hora >= 9 && hora < 20) ||
         (dia === 6 && hora >= 9 && hora < 15);
}

function formatearISO(fecha) {
  const pad = n => String(n).padStart(2, '0');
  return `${fecha.getFullYear()}-${pad(fecha.getMonth() + 1)}-${pad(fecha.getDate())}` +
         `T${pad(fecha.getHours())}:${pad(fecha.getMinutes())}:${pad(fecha.getSeconds())}-05:00`;
}

