    pasadoMañana.setDate(ahora.getDate() + 2);
    const tiempoInfo = parsearHora(texto);
    return crearFecha(pasadoMañana.getFullYear(), pasadoMañana.getMonth(), pasadoMañana.getDate(), tiempoInfo.hora, tiempoInfo.minuto);
  }

  if (texto.includes('manana')) {
    const mañana = new Date(ahora);
    mañana.setDate(ahora.getDate() + 1);
    const tiempoInfo = parsearHora(texto);
    return crearFecha(mañana.getFullYear(), mañana.getMonth(), mañana.getDate(), tiempoInfo.hora, tiempoInfo.minuto);
  }

  // Resto del código permanece igual...
  const tiempoInfo = parsearHora(texto);

  // Formato ISO: Solo permitir si el usuario realmente escribió una fecha ISO
  // NOTA: Este formato está limitado a casos muy específicos donde el usuario
  // efectivamente escriba una fecha en formato ISO (muy raro)
