    let hora = tiempoInfo.hora;
    let minuto = tiempoInfo.minuto;

    // Si tiene hora en el ISO, usarla
    if (isoMatch[4] && isoMatch[5]) {
      hora = parseInt(isoMatch[4], 10);
      minuto = parseInt(isoMatch[5], 10);
    }

    return crearFecha(año, mes, dia, hora, minuto);
  }

  // Formato "DD de MES"
  const españolMatch = texto.match(/(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)/);
  if (españolMatch) {
    const dia = parseInt(españolMatch[1], 10);
    const nombreMes = españolMatch[2];
    const mes = MESES[nombreMes];

    let año = ahora.getFullYear();
    let fechaTest = crearFecha(año, mes, dia, tiempoInfo.hora, tiempoInfo.minuto);

    // Si ya pasó este año, usar el próximo
