    }

    return fechaTest;
  }

  // Formato "DD/MM" o "DD/MM/YYYY"
  const slashMatch = texto.match(/(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?/);
  if (slashMatch) {
    const dia = parseInt(slashMatch[1], 10);
    const mes = parseInt(slashMatch[2], 10) - 1;
