const consolidated = unique.join(' ');

// 6) Devolver
return [{
  json: {
    context_id: j.context_id,
    message: consolidated,
  }
}];

/**
 * n8n Code node (JavaScript)
 * Normaliza la entrada de chat a un JSON único con campos limpios.
 * Asegura user_id, lead_source y city buscando en varias rutas y con deep search.
 */

function firstTruthy(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && v !== '' && !(typeof v === 'number' && isNaN(v))) {
      return v;
    }
  }
  return null;
}

function getByPath(obj, path) {
  if (!obj || !path) return undefined;
  try {
    return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
  } catch {
    return undefined;
  }
}

function deepFindByKeyNames(obj, keyNames = new Set(), maxDepth = 8) {
  const stack = [{ o: obj, d: 0 }];
  while (stack.length) {
    const { o, d } = stack.pop();
    if (!o || typeof o !== 'object' || d > maxDepth) continue;
    for (const [k, v] of Object.entries(o)) {
      if (keyNames.has(k) && v !== undefined && v !== null && v !== '') return v;
      if (v && typeof v === 'object') stack.push({ o: v, d: d + 1 });
    }
  }
  return undefined;
}

function pickValue(obj, paths = [], keyNames = []) {
  // 1) prueba rutas explícitas
  for (const p of paths) {
    const v = getByPath(obj, p);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  // 2) búsqueda profunda por nombre de clave
  if (keyNames.length) {
    const v = deepFindByKeyNames(obj, new Set(keyNames));
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}

