    data.phone,
    sender.phone_number,
    getByPath(body, 'inbox.sender.phone_number'),
    pickValue(data, [], ['phone', 'telefono', 'celular'])
  );

  const email = firstTruthy(
    data.email,
    sender.email,
    getByPath(body, 'inbox.sender.email'),
    pickValue(data, [], ['email', 'correo'])
  );

