    meta.city,
    data.city,
    sender.city,
    pickValue(data, ['route.sheetLookup.city'], ['city', 'ciudad'])
  );

  // --- Mensaje ---
  const message = firstTruthy(
    msg0.content,
    body.message,
    data.message,
    getByPath(data, 'payload.message')
  );

