  const distancia = firstTruthy(
    getByPath(data, 'distancia.mensaje'),
    data.distancia,
    meta.distancia
  );

  // --- Meta ---
  const metaOut = {
    canal: firstTruthy(data.canal, body.canal, meta.canal, lead_source, 'whatsapp'),
    timestamp: firstTruthy(data.timestamp, meta.timestamp, new Date().toISOString()),
  };

  const resumen = {
    user_id: user_id ?? null,
    name: name ?? null,
    phone: phone ?? null,
    email: email ?? null,
    lead_source,                         // garantizado (o "unknown")
    status_lead: data.status_lead || 'COLD',
    message: message ?? null,
    city: city ?? null,
    distancia: distancia ?? null,
    meta: metaOut,
  };

  return { json: resumen };
});

